-- Coach-level move (SAFETY-01, 20261017090000). Written, not applied.
-- Coach-level move (SAFETY-01). Design: docs/engineering/design/COACH_LEVEL_LABEL_DESIGN.md
-- Written 2026-10-16. Applied: development 2026-10-22 (Claude Code; hosted bodies match the replay). Staging waits for
-- Beyond, which it alters (feature freeze). Replay: scripts/replay/coach-level-replay.mjs.
-- 2026-10-22 (workstream 4 RLS review): the app sets the label at insert, which skipped the Train Like Me rule
-- and the audit row; reels_audit_coach_label now enforces both on insert. Also fixed before any apply: client inserts
-- could not write safety_label (column grant), report_reel's count was ambiguous (every report failed), and the
-- 20-minute window compared against a zone-less timestamp.
-- Adds reels.safety_label and beyond_posts.safety_label (none | coach_level, default none),
-- an append-only audit, admin add/remove with a reason, and an uploader set only on a new upload.
-- A "Risky without a coach" report is stored and never hides the clip.
-- Needs: reels, beyond_posts, reel_reports, reels_feed, beyond_post_json, report_reel, caller_not_age_blocked.
-- Rollback: drop function public.coach_label_desk(); drop function public.set_coach_label(text,uuid,text,text);
--   drop function public.set_own_coach_label(text,uuid,text);
--   drop trigger if exists reels_guard_coach_label on public.reels;
--   drop trigger if exists beyond_posts_guard_coach_label on public.beyond_posts;
--   drop function public.guard_coach_label();
--   drop trigger if exists reels_audit_coach_label on public.reels; drop function public.audit_coach_label_on_insert();
--   alter table public.reels drop column if exists safety_label;
--   alter table public.beyond_posts drop column if exists safety_label;
--   drop table if exists public.safety_label_events;
--   The replaced view and report_reel stay at this definition; restore them from the previous migration if rolling back.

alter table public.reels add column if not exists safety_label text not null default 'none';
alter table public.reels drop constraint if exists reels_safety_label_check;
alter table public.reels add constraint reels_safety_label_check check (safety_label in ('none','coach_level'));

alter table public.beyond_posts add column if not exists safety_label text not null default 'none';
alter table public.beyond_posts drop constraint if exists beyond_posts_safety_label_check;
alter table public.beyond_posts add constraint beyond_posts_safety_label_check check (safety_label in ('none','coach_level'));

create table if not exists public.safety_label_events (
  id uuid primary key default gen_random_uuid(),
  target_kind text not null check (target_kind in ('reel','beyond_post')),
  target_id uuid not null,
  old_label text not null,
  new_label text not null,
  actor_id uuid,
  reason text not null,
  created_at timestamptz not null default timezone('utc', now())
);
alter table public.safety_label_events enable row level security;
drop policy if exists "Admin reads safety label events" on public.safety_label_events;
create policy "Admin reads safety label events" on public.safety_label_events for select to authenticated
  using (public.current_user_role() = 'admin');
drop policy if exists "Closed accounts" on public.safety_label_events;
create policy "Closed accounts" on public.safety_label_events as restrictive for all to authenticated
  using ((select public.caller_not_age_blocked())) with check ((select public.caller_not_age_blocked()));
revoke all on public.safety_label_events from public, anon, authenticated;
grant select on public.safety_label_events to authenticated;

alter table public.reel_reports drop constraint if exists reel_reports_reason_check;
alter table public.reel_reports add constraint reel_reports_reason_check check (
  reason in ('fake_footage','wrong_athlete','impersonation','rights','inappropriate','other','unspecified','coach_level')
);

create or replace function public.guard_coach_label()
returns trigger language plpgsql as $$
begin
  if new.safety_label is distinct from old.safety_label
     and current_setting('tapuai.coach_label', true) is distinct from '1' then
    raise exception 'A coach-level label changes only through review.';
  end if;
  return new;
end $$;
drop trigger if exists reels_guard_coach_label on public.reels;
create trigger reels_guard_coach_label before update on public.reels
  for each row execute function public.guard_coach_label();
drop trigger if exists beyond_posts_guard_coach_label on public.beyond_posts;
create trigger beyond_posts_guard_coach_label before update on public.beyond_posts
  for each row execute function public.guard_coach_label();

-- Uploads set the label on insert (MediaUploadService). Same rule and audit as set_own_coach_label; uploaded_by is
-- already forced to the caller by reels_apply_tag_defaults. Security definer only to write the admin-only audit.
create or replace function public.audit_coach_label_on_insert()
returns trigger language plpgsql security definer set search_path = '' as $$
begin
  if new.safety_label = 'coach_level' then
    if new.category is distinct from 'train_like_me' then
      raise exception 'Only a Train Like Me clip can be marked as an advanced move.';
    end if;
    insert into public.safety_label_events(target_kind, target_id, old_label, new_label, actor_id, reason)
    values ('reel', new.id, 'none', 'coach_level', new.uploaded_by, 'uploader');
  end if;
  return null;
end $$;
drop trigger if exists reels_audit_coach_label on public.reels;
create trigger reels_audit_coach_label after insert on public.reels
  for each row execute function public.audit_coach_label_on_insert();

create or replace function public.set_own_coach_label(target_kind text, target_id uuid, label text)
returns jsonb language plpgsql security definer set search_path = public as $$
declare me uuid := public.my_profile_id();
begin
  if me is null then raise exception 'Sign in to mark an advanced move.'; end if;
  if label is distinct from 'coach_level' or target_kind not in ('reel','beyond_post') or target_id is null then
    raise exception 'Check the coach-level label.';
  end if;
  perform set_config('tapuai.coach_label', '1', true);
  if target_kind = 'reel' then
    update public.reels set safety_label = 'coach_level'
     where id = target_id and uploaded_by = me and category = 'train_like_me' and safety_label = 'none'
       and created_at > now() - interval '20 minutes';
    if not found then raise exception 'Only the uploader can mark a new Train Like Me clip.'; end if;
  else
    update public.beyond_posts set safety_label = 'coach_level'
     where id = target_id and owner_id = me and category = 'workout' and safety_label = 'none'
       and status in ('draft','pending');
    if not found then raise exception 'Only the uploader can mark a new workout before it is shared.'; end if;
  end if;
  insert into public.safety_label_events(target_kind, target_id, old_label, new_label, actor_id, reason)
  values (target_kind, target_id, 'none', 'coach_level', me, 'uploader');
  return jsonb_build_object('target_kind', target_kind, 'target_id', target_id, 'safety_label', 'coach_level');
end $$;

create or replace function public.set_coach_label(target_kind text, target_id uuid, label text, reason text)
returns jsonb language plpgsql security definer set search_path = public as $$
declare me uuid := public.my_profile_id(); old text; why text := btrim(coalesce(reason,''));
begin
  if public.current_user_role() is distinct from 'admin' or me is null then raise exception 'An admin reviews coach-level labels.'; end if;
  if target_kind not in ('reel','beyond_post') or target_id is null or label not in ('none','coach_level') or char_length(why) < 8 or char_length(why) > 240 then
    raise exception 'Add a reason of at least 8 characters.';
  end if;
  perform set_config('tapuai.coach_label', '1', true);
  if target_kind = 'reel' then
    select safety_label into old from public.reels where id = target_id for update;
    if old is null then raise exception 'Highlight not found.'; end if;
    update public.reels set safety_label = label where id = target_id;
  else
    select safety_label into old from public.beyond_posts where id = target_id for update;
    if old is null then raise exception 'Beyond post not found.'; end if;
    update public.beyond_posts set safety_label = label where id = target_id;
  end if;
  if old is distinct from label then
    insert into public.safety_label_events(target_kind, target_id, old_label, new_label, actor_id, reason)
    values (target_kind, target_id, old, label, me, why);
  end if;
  return jsonb_build_object('target_kind', target_kind, 'target_id', target_id, 'safety_label', label);
end $$;

create or replace function public.coach_label_desk()
returns jsonb language plpgsql stable security definer set search_path = public as $$
declare labelled_reels int; labelled_posts int; open_suggestions int; median_hours numeric; suggestions jsonb; events jsonb;
begin
  if public.current_user_role() is distinct from 'admin' then raise exception 'An admin reviews coach-level labels.'; end if;
  select count(*) into labelled_reels from public.reels where safety_label = 'coach_level';
  select count(*) into labelled_posts from public.beyond_posts where safety_label = 'coach_level';
  select count(*) into open_suggestions from (
    select r.id from public.reels r
    where r.safety_label = 'none' and exists (select 1 from public.reel_reports rr where rr.reel_id = r.id and rr.reason = 'coach_level')
  ) s;
  select percentile_cont(0.5) within group (order by extract(epoch from (reviewed - suggested)) / 3600) into median_hours
  from (
    select e.created_at as reviewed,
      (select min(rr.created_at) from public.reel_reports rr where rr.reel_id = e.target_id and rr.reason = 'coach_level' and rr.created_at <= e.created_at) as suggested
    from public.safety_label_events e
    where e.target_kind = 'reel' and e.created_at >= date_trunc('week', timezone('utc', now()))
  ) reviews where suggested is not null;
  select coalesce(jsonb_agg(row_to_json(q)), '[]'::jsonb) into suggestions from (
    select 'reel' as kind, r.id, r.title, (select count(*) from public.reel_reports rr where rr.reel_id = r.id and rr.reason = 'coach_level') as reports
    from public.reels r
    where r.safety_label = 'none' and exists (select 1 from public.reel_reports rr where rr.reel_id = r.id and rr.reason = 'coach_level')
    order by r.created_at desc limit 50
  ) q;
  select coalesce(jsonb_agg(row_to_json(q)), '[]'::jsonb) into events from (
    select e.id, e.target_kind, e.target_id, e.old_label, e.new_label, e.actor_id, e.reason, e.created_at
    from public.safety_label_events e order by e.created_at desc limit 50
  ) q;
  return jsonb_build_object(
    'labelled_reels', labelled_reels,
    'labelled_posts', labelled_posts,
    'open_suggestions', open_suggestions,
    'median_review_hours', median_hours,
    'suggestions', suggestions,
    'events', events
  );
end $$;

revoke all on function public.guard_coach_label() from public, anon, authenticated;
revoke all on function public.audit_coach_label_on_insert() from public, anon, authenticated;
-- Uploads send the label on insert; the 2026-10-13 column list predates it. The audit trigger enforces the rule.
grant insert (safety_label) on public.reels to authenticated;
revoke all on function public.set_own_coach_label(text, uuid, text) from public, anon;
revoke all on function public.set_coach_label(text, uuid, text, text) from public, anon;
revoke all on function public.coach_label_desk() from public, anon;
grant execute on function public.set_own_coach_label(text, uuid, text) to authenticated;
grant execute on function public.set_coach_label(text, uuid, text, text) to authenticated;
grant execute on function public.coach_label_desk() to authenticated;


create or replace view public.reels_feed as
select
  r.id,
  r.title,
  -- A pending tag names the athlete only to the uploader, the athlete, their guardian and admins; a rejected tag names
  -- nobody (PRIV-01 stage 2, MINOR_SAFETY): a stranger's clip must not show a private athlete before they agree.
  case
    when r.tag_status = 'rejected' and public.current_user_role() is distinct from 'admin' then null
    when r.tag_status = 'pending' and not public.tag_party(r.uploaded_by, r.player_id) then null
    else r.player_id
  end as player_id,
  r.game_id,
  r.created_at,
  r.seki_count,
  r.aura_count,
  r.flex_count,
  r.total_tips_cents,
  r.is_exclusive,
  r.is_vault_only,
  r.is_flagged,
  r.reported_by,
  r.is_removed,
  r.category,
  r.flash_unlock_until,
  r.uploaded_by,
  -- A blocked uploader's quiet rejection and a real decline look the same (see reels_apply_tag_defaults).
  r.tag_status,
  -- Who decided, and when, only on an approved tag (a decline must not reveal the athlete or guardian).
  case when r.tag_status = 'confirmed' or public.current_user_role() = 'admin' then r.tag_confirmed_at else null end as tag_confirmed_at,
  case when r.tag_status = 'confirmed' or public.current_user_role() = 'admin' then r.tag_confirmed_by else null end as tag_confirmed_by,
  case
    when coalesce(r.is_vault_only, false) = false then r.video_url
    when r.flash_unlock_until is not null and r.flash_unlock_until > timezone('utc', now()) then r.video_url
    when public.current_user_role() = 'admin' then r.video_url
    when auth.uid() is not null and r.uploaded_by = (
      select p.id from public.profiles p where p.user_id = auth.uid() limit 1
    ) then r.video_url
    when auth.uid() is not null and r.player_id is not null and exists (
      select 1 from public.subscriptions s
      where s.subscriber_id = auth.uid()
        and s.athlete_id = r.player_id
        and s.status = 'active'
    ) then r.video_url
    else ''
  end as video_url,
  coalesce(r.view_count, 0) as view_count,
  -- Handle first, else first name only: the clip credit never shows a fan's full name.
  -- Null when the tagged athlete posted it themself (no "Filmed by" on your own clip).
  case
    when r.player_id is not null and up.player_id = r.player_id then null
    else coalesce(
      nullif(btrim(up.username), ''),
      nullif(split_part(btrim(coalesce(up.full_name, '')), ' ', 1), '')
    )
  end as uploader_name,
  public.visible_avatar_url(up.id) as uploader_avatar_url,
  r.media_type,
  r.photo_count,
  (
    select case
      when coalesce(r.is_vault_only, false) = false then ph.image_path
      when r.flash_unlock_until is not null and r.flash_unlock_until > timezone('utc', now()) then ph.image_path
      when public.current_user_role() = 'admin' then ph.image_path
      when auth.uid() is not null and r.uploaded_by = (
        select p.id from public.profiles p where p.user_id = auth.uid() limit 1
      ) then ph.image_path
      when auth.uid() is not null and r.player_id is not null and exists (
        select 1 from public.subscriptions s
        where s.subscriber_id = auth.uid()
          and s.athlete_id = r.player_id
          and s.status = 'active'
      ) then ph.image_path
      else ''
    end
    from public.reel_photos ph
    where ph.reel_id = r.id and ph.position = 0
  ) as cover_path,
  r.safety_label
from public.reels r
left join public.profiles up on up.id = r.uploaded_by;

create or replace function public.beyond_post_json(target uuid,admin_detail boolean default false)
returns jsonb language plpgsql stable security definer set search_path='' as $$
#variable_conflict use_variable
declare p public.beyond_posts;result jsonb;begin
 select * into p from public.beyond_posts where id=target;
 if not found then return null;end if;
 result:=jsonb_build_object('id',p.id,'creator_id',p.owner_id,'category',p.category,'caption',p.caption,'audience',p.audience,'status',p.status,'revision',p.revision,'created_at',p.created_at,'submitted_at',p.submitted_at,'rights_version',p.rights_version,'safety_version',p.safety_version,'safety_label',coalesce(p.safety_label,'none'),'attested_at',p.attested_at,'cleanup',p.cleanup,'media',coalesce((select jsonb_agg(jsonb_build_object('id',m.id,'position',m.position,'kind',m.kind,'path',m.path,'mime',m.mime,'bytes',m.bytes,'width',m.width,'height',m.height,'duration_ms',m.duration_ms) order by m.position) from public.beyond_media m where m.post_id=p.id),'[]'));
 if admin_detail or public.my_profile_id()=p.owner_id then result:=result||jsonb_build_object('review_reason',p.review_reason,'reviewed_at',p.reviewed_at,'cleanup_checked_at',p.cleanup_checked_at);end if;
 if admin_detail then result:=result||jsonb_build_object('report_count',(select count(*) from public.beyond_reports r where r.post_id=p.id));end if;
 return result;end$$;

create or replace function public.report_reel(target_reel_id uuid, report_reason text)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  reporter uuid := auth.uid();
  reason text := coalesce(nullif(trim(report_reason), ''), 'unspecified');
  result public.reels%rowtype;
  report_count integer := 0;
  hides_now boolean := false;
begin
  if reporter is null then
    raise exception 'Sign in to report a highlight.';
  end if;
  if reason not in (
    'fake_footage', 'wrong_athlete', 'impersonation', 'rights', 'inappropriate', 'other', 'unspecified', 'coach_level'
  ) then
    raise exception 'Pick a report reason.';
  end if;

  insert into public.reel_reports (reel_id, reporter_id, reason)
  values (target_reel_id, reporter, reason)
  on conflict (reel_id, reporter_id) do update
    set reason = excluded.reason;

  -- A coach-level suggestion never hides the clip and does not count toward the three-report hide.
  select count(*)::integer into report_count
  from public.reel_reports rr
  where rr.reel_id = target_reel_id and rr.reason is distinct from 'coach_level';

  if reason = 'coach_level' then
    update public.reels
    set reported_by = case
      when coalesce(reported_by, '{}'::uuid[]) @> array[reporter] then coalesce(reported_by, '{}'::uuid[])
      else array_append(coalesce(reported_by, '{}'::uuid[]), reporter)
    end
    where id = target_reel_id
    returning * into result;
  else
    select exists (
      select 1
      from public.reels r
      join public.profiles me on me.user_id = reporter
      where r.id = target_reel_id
        and (
          me.player_id = r.player_id
          or exists (
            select 1 from public.custodial_accounts ca
            where ca.player_id = r.player_id and ca.guardian_id = me.id
          )
          or exists (
            select 1 from public.players pl
            where pl.id = r.player_id and pl.guardian_id = me.id
          )
        )
    ) into hides_now;

    if reason in ('fake_footage', 'impersonation', 'rights') then
      hides_now := true;
    end if;

    update public.reels
    set
      is_flagged = hides_now or report_count >= 3 or coalesce(is_flagged, false),
      reported_by = case
        when coalesce(reported_by, '{}'::uuid[]) @> array[reporter] then coalesce(reported_by, '{}'::uuid[])
        else array_append(coalesce(reported_by, '{}'::uuid[]), reporter)
      end
    where id = target_reel_id
    returning * into result;
  end if;

  if result.id is null then
    raise exception 'Highlight not found.';
  end if;

  return jsonb_build_object(
    'id', result.id,
    'is_flagged', result.is_flagged,
    'reported_by', result.reported_by,
    'reason', reason,
    'report_count', report_count
  );
end;
$$;

-- IQ questions in the weekly trivia mix (20261017110000). Written, not applied.
-- IQ questions in the weekly trivia mix.
-- A personal sport round draws one unseen IQ question (topic general, sport IQ) once per round,
-- then continues with sport questions. Written, not applied.
-- Rollback: delete from public.sport_quiz_questions where sport = 'IQ' and topic_category = 'general';
-- then restore quiz_round_pick from 20261015210000_trivia_fresh_questions.sql.

create or replace function public.quiz_round_pick(p_me uuid,p_attempt uuid,p_position integer)
returns uuid language plpgsql security definer set search_path = '' as $$
declare a public.sport_quiz_attempts%rowtype; qid uuid; hard_full boolean;
begin
  select * into a from public.sport_quiz_attempts where id = p_attempt;
  hard_full := public.quiz_round_hard_count(a.id) >= 2;
  if a.round_kind = 'life' then
    select q.id into qid from public.sport_quiz_questions q where q.id in (select x.id from public.quiz_life_pool(p_me,a.sport_filter) x)
      and (not hard_full or not public.quiz_question_hard(q.id)) order by random() limit 1 for share of q;
    return qid;
  end if;
  if a.group_id is not null then
    select q.id into qid from public.sport_quiz_group_sets gs join public.sport_quiz_questions q on q.id = gs.question_id
      where gs.group_id = a.group_id and gs.week_start = a.week_start and gs.position = p_position
        and q.status = 'approved' and q.question_type <> 'image_choice' and public.quiz_normalize_options(q.options) is not null
        and char_length(btrim(q.source_notes)) >= 10 and not public.quiz_question_paused(q.id)
        and not exists(select 1 from public.sport_quiz_exposures e where e.profile_id = p_me and e.question_key = gs.question_key)
      for share of q;
    if qid is not null then return qid; end if;
    select q.id into qid from public.sport_quiz_questions q
      where q.status = 'approved' and q.question_type <> 'image_choice' and q.topic_category = 'sport' and (a.sport_filter is null or q.sport = a.sport_filter)
        and public.quiz_normalize_options(q.options) is not null and char_length(btrim(q.source_notes)) >= 10 and not public.quiz_question_paused(q.id)
        and (not hard_full or not public.quiz_question_hard(q.id))
        and not exists(select 1 from public.sport_quiz_exposures e where e.profile_id = p_me and e.question_key = q.question_key)
      order by exists(select 1 from public.sport_quiz_group_sets gs where gs.group_id = a.group_id and gs.week_start = a.week_start
                        and gs.position > p_position and gs.question_key = q.question_key), random()
      limit 1 for share of q;
    return qid;
  end if;
  if p_position = public.quiz_fact_slot(p_me,a.id) then
    qid := public.quiz_fact_pick(p_me,a.id);
    if qid is not null then return qid; end if;
  end if;
  -- One IQ question in a personal sport round, before the ordinary sport draw.
  if a.topic_category = 'sport' and not exists (
      select 1 from public.sport_quiz_round_items i
      join public.sport_quiz_questions asked on asked.id = i.question_id
      where i.attempt_id = a.id and asked.sport = 'IQ') then
    select q.id into qid from public.sport_quiz_questions q
      where q.status = 'approved' and q.question_type <> 'image_choice' and q.topic_category = 'general' and q.sport = 'IQ'
        and public.quiz_normalize_options(q.options) is not null and char_length(btrim(q.source_notes)) >= 10 and not public.quiz_question_paused(q.id)
        and not exists(select 1 from public.sport_quiz_exposures e where e.profile_id = p_me and e.question_key = q.question_key)
      order by random() limit 1 for share of q;
    if qid is not null then return qid; end if;
  end if;
  select q.id into qid from public.sport_quiz_questions q
    where q.status = 'approved' and q.question_type <> 'image_choice' and q.topic_category = a.topic_category and a.topic_category not in ('life','athlete')
      and (a.sport_filter is null or q.sport = a.sport_filter)
      and public.quiz_normalize_options(q.options) is not null and char_length(btrim(q.source_notes)) >= 10 and not public.quiz_question_paused(q.id)
      and (not hard_full or not public.quiz_question_hard(q.id))
      and not exists(select 1 from public.sport_quiz_exposures e where e.profile_id = p_me and e.question_key = q.question_key)
    order by random() limit 1 for share of q;
  return qid;
end $$;

insert into public.sport_quiz_questions
  (question_key, version, sport, prompt, options, correct_option, explanation, status, reason, topic_category, source_notes, question_type)
select v.key, 1, 'IQ', v.prompt, v.options::jsonb, v.correct_option, v.explanation, 'approved',
  'Simple reasoning item for the weekly trivia mix.', 'general',
  'Public reasoning item. Not a school score or a medical claim.', 'choice4'
from (values
  ('a1b2c3d4-e5f6-4789-a012-000000000001'::uuid, 'What number comes next: 2, 4, 8, 16?', '["32","18","24","12"]', 0, 'Each number is double the one before it, so 16 doubles to 32.'),
  ('a1b2c3d4-e5f6-4789-a012-000000000002'::uuid, 'Which word does not belong with the others?', '["Carrot","Apple","Banana","Grape"]', 0, 'Apple, banana and grape are fruits. A carrot is a vegetable.'),
  ('a1b2c3d4-e5f6-4789-a012-000000000003'::uuid, 'If every bloops is a razzle, and every razzle is a lazzle, is every bloops a lazzle?', '["Yes","No","Only some","Cannot tell"]', 0, 'If every bloops is a razzle and every razzle is a lazzle, then every bloops is a lazzle.'),
  ('a1b2c3d4-e5f6-4789-a012-000000000004'::uuid, 'A cap and a shirt together cost 30 dollars. The shirt costs 20 dollars more than the cap. What does the cap cost?', '["5 dollars","10 dollars","15 dollars","20 dollars"]', 0, 'The cap is 5 dollars and the shirt is 25 dollars. Together they are 30, and the shirt is 20 more.'),
  ('a1b2c3d4-e5f6-4789-a012-000000000005'::uuid, 'Which shape has exactly three sides?', '["Triangle","Square","Circle","Hexagon"]', 0, 'A triangle has three sides. A square has four, a hexagon has six, and a circle has none.'),
  ('a1b2c3d4-e5f6-4789-a012-000000000006'::uuid, 'What letter comes next: A, C, E, G?', '["I","H","J","F"]', 0, 'The letters skip one each time: A, C, E, G, then I.')
) as v(key, prompt, options, correct_option, explanation)
where not exists (select 1 from public.sport_quiz_questions q where q.question_key = v.key);

-- ---------------------------------------------------------------------------------------------------------------
-- Live score Broadcast (SCALE-03, 20261018120000). Written, not applied. Copy of the migration file.
-- ---------------------------------------------------------------------------------------------------------------
-- SCALE-03 · Live score Broadcast (2026-10-18). Written locally, NOT applied anywhere.
--
-- Purpose: stop the game-night refetch storm (HOSTING_DECISION_BRIEF §7 item 5). Today `useLiveScores` listens to
-- `postgres_changes` on every `games` row and rereads the whole list on any change, so every fan rereads every game
-- on every score. After this file, each scoreboard change is sent once on a private per-game Broadcast topic
-- (`game_scores_{id}`) carrying only the changed columns and a per-game sequence number; game add / remove /
-- active flips go to `game_scores_index` so the list rereads only then.
--
-- What it adds:
--   1. `games.live_seq bigint` — bumped by a BEFORE trigger only when a scoreboard column changes, so a client can
--      drop duplicates / older messages and detect a missed one (gap → reread). Clients cannot set it.
--   2. AFTER trigger `games_broadcast_score_change` → `realtime.send(..., private => true)`. Payload
--      `{v:1, id, seq, changes:{<changed scoreboard columns>}}`, event `score`. `claimed_by` and other columns are
--      never sent. Membership payload `{v:1, id, op:'insert'|'delete'|'active'}`, event `membership`.
--      A failed send never blocks the score update (warning only).
--   3. `realtime.messages` SELECT policy: anon + authenticated may receive Broadcast on exactly
--      `game_scores_<uuid>` and `game_scores_index` (the same people who can already read `games`: "Public read
--      games" is `using (true)`). No INSERT policy is added, so no client can send on these topics; only the
--      definer trigger writes them. Presence is not allowed (extension must be 'broadcast').
--
-- Client: `apps/mobile/src/frontend/lib/liveScoreSync.ts`. The app uses these topics only when the build sets
-- `EXPO_PUBLIC_LIVE_SCORES_BROADCAST=true`; if the policy is missing it falls back to today's path on its own.
-- Apply order: after every earlier file (needs `games.sport` and `games.is_active`). Staging first.
--
-- Rollback (safe at any time; turn the app switch off first):
--   drop trigger if exists games_broadcast_score_change on public.games;
--   drop trigger if exists games_live_seq_bump on public.games;
--   drop function if exists public.games_broadcast_score_change();
--   drop function if exists public.games_live_seq_bump();
--   drop policy if exists "Fans receive game score changes" on realtime.messages;
--   -- optional, only once no build reads it: alter table public.games drop column if exists live_seq;

alter table public.games add column if not exists live_seq bigint not null default 0;

-- Clients (operator console, admin desk) write `games` directly; this keeps `live_seq` server-owned and moves it only
-- when something a fan sees changes, so the AFTER trigger and the client agree on "one change = one number".
create or replace function public.games_live_seq_bump()
returns trigger
language plpgsql
set search_path = ''
as $$
begin
  if tg_op = 'INSERT' then
    new.live_seq := 0;
    return new;
  end if;
  if (new.home_score, new.away_score, new.quarter, new.status, new.clock, new.is_clock_running, new.is_active,
      new.home_team, new.away_team, new.home_school, new.away_school, new.venue, new.sport)
     is distinct from
     (old.home_score, old.away_score, old.quarter, old.status, old.clock, old.is_clock_running, old.is_active,
      old.home_team, old.away_team, old.home_school, old.away_school, old.venue, old.sport) then
    new.live_seq := coalesce(old.live_seq, 0) + 1;
  else
    new.live_seq := old.live_seq;
  end if;
  return new;
end;
$$;

drop trigger if exists games_live_seq_bump on public.games;
create trigger games_live_seq_bump
  before insert or update on public.games
  for each row execute function public.games_live_seq_bump();

-- Security definer: `realtime.send` writes `realtime.messages`, which clients may not insert into on these topics.
-- Same pattern as Supabase's documented Broadcast-from-database triggers.
create or replace function public.games_broadcast_score_change()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare
  fields constant text[] := array['home_score', 'away_score', 'quarter', 'status', 'clock', 'is_clock_running',
    'is_active', 'home_team', 'away_team', 'home_school', 'away_school', 'venue', 'sport', 'updated_at'];
  field text;
  next_row jsonb;
  prev_row jsonb;
  changes jsonb := '{}'::jsonb;
begin
  begin
    if tg_op = 'UPDATE' then
      if new.live_seq is not distinct from old.live_seq then
        return null; -- e.g. a claimed_by-only update: nothing a fan sees changed
      end if;
      next_row := to_jsonb(new);
      prev_row := to_jsonb(old);
      foreach field in array fields loop
        if next_row -> field is distinct from prev_row -> field then
          changes := changes || jsonb_build_object(field, next_row -> field);
        end if;
      end loop;
      perform realtime.send(
        jsonb_build_object('v', 1, 'id', new.id, 'seq', new.live_seq, 'changes', changes),
        'score', 'game_scores_' || new.id::text, true);
      if new.is_active is distinct from old.is_active then
        perform realtime.send(jsonb_build_object('v', 1, 'id', new.id, 'op', 'active'),
          'membership', 'game_scores_index', true);
      end if;
    elsif tg_op = 'INSERT' then
      perform realtime.send(jsonb_build_object('v', 1, 'id', new.id, 'op', 'insert'),
        'membership', 'game_scores_index', true);
    elsif tg_op = 'DELETE' then
      perform realtime.send(jsonb_build_object('v', 1, 'id', old.id, 'op', 'delete'),
        'membership', 'game_scores_index', true);
    end if;
  exception when others then
    -- A scoreboard update must never fail because Realtime could not take the message; fans reread on reconnect.
    raise warning 'games_broadcast_score_change: % (%)', sqlerrm, sqlstate;
  end;
  return null;
end;
$$;

drop trigger if exists games_broadcast_score_change on public.games;
create trigger games_broadcast_score_change
  after insert or update or delete on public.games
  for each row execute function public.games_broadcast_score_change();

-- Trigger functions are never RPCs; keep them off the API roles (Supabase default privileges grant EXECUTE).
revoke all on function public.games_live_seq_bump() from public, anon, authenticated;
revoke all on function public.games_broadcast_score_change() from public, anon, authenticated;

-- Receive-only, exact topic shapes. `realtime.messages` already has RLS on (platform-owned; do not alter it).
drop policy if exists "Fans receive game score changes" on realtime.messages;
create policy "Fans receive game score changes"
  on realtime.messages for select
  to anon, authenticated
  using (
    realtime.messages.extension = 'broadcast'
    and realtime.topic() ~ '^game_scores_([0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}|index)$'
  );

